using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

namespace PowerShapeBridge {
 internal static class OwnedGeometryExportTests {
  static void Require(bool ok,string error){if(!ok)throw new InvalidOperationException(error);}
  static Dictionary<string,object> Clone(Dictionary<string,object> value){return Program.Json.Deserialize<Dictionary<string,object>>(Program.Json.Serialize(value));}
  static Dictionary<string,string> Hashes(string root){return Directory.GetFiles(root,"*",SearchOption.AllDirectories).ToDictionary(p=>p,p=>Program.Hash(p));}
  internal sealed class Context : OwnedGeometryExport.IContext {
   internal Dictionary<string,object> Snapshot,Listing,Settings=new Dictionary<string,object>{{"translator","built_in_local"},{"triangulationToleranceRaw",0.01},{"solidShading",true},{"limitTriangleEdgeLength",false},{"maximumTriangleEdgeLengthRaw",null},{"toleranceLengthUnits","document_raw"},{"providerQualification","synthetic_only"}};
   internal readonly List<Dictionary<string,object>> Selected=new List<Dictionary<string,object>>();internal string Fault,TargetPath,Root;internal int Adds,Exports,Clears,Reads,MapReads;internal bool Changed;
   internal Context(OwnedOperationPlanTests.Fixture fixture){Root=fixture.Root;Snapshot=Clone(fixture.Snapshot);Listing=Clone(fixture.Listing);}
   public Dictionary<string,object> Windows(){return Clone(Listing);}
   public Dictionary<string,object> Observation(){Reads++;var value=Clone(Snapshot);value["contextBefore"]=value["contextAfter"]=new[]{Selected.Count,0};value["selectionBefore"]=value["selectionAfter"]=Selected.ToArray();if(Fault=="late_document"&&Adds>0||Fault=="claimed_context"&&Reads>=3)((Dictionary<string,object>)value["model"])["id"]=99;return value;}
   public void ConfirmDocument(){if(Changed)throw new InvalidOperationException("Retained fake document changed.");}
   public Dictionary<string,object> ExportSettings(){return Settings;}
   public int Composite(int type,int id){MapReads++;return Fault=="wrong_mapping"&&MapReads==1?999:type*100000+id;}
   public void AddSelection(int type,int id,string name){Adds++;Selected.Add(new Dictionary<string,object>{{"type",type==40?"SOLID":"SURFACE"},{"name",name}});if(Fault=="wrong_selection")Selected[Selected.Count-1]["name"]="Foreign";if(Fault=="select_throw")throw new IOException("Unknown selection callback.");if(Fault=="settings_after_select")Settings["triangulationToleranceRaw"]=0.02;if(Fault=="selection_collision")File.WriteAllText(TargetPath,"Opaque collision.");if(Fault=="retained_document")Changed=true;}
   public void ExportDmt(string path){Exports++;if(Fault=="export_throw")throw new IOException("Unknown export callback.");if(Fault=="no_output")return;if(Fault=="malformed_output"){File.WriteAllText(path,"Not a DMT.");return;}if(Fault=="output_directory"){Directory.CreateDirectory(path);return;}
    using(var file=new FileStream(path,FileMode.CreateNew,FileAccess.Write,FileShare.None))using(var writer=new BinaryWriter(file)) {writer.Write(System.Text.Encoding.ASCII.GetBytes("Own synthetic triangles\0"));writer.Write((ushort)1000);writer.Write(2u);writer.Write(1u);writer.Write(3u);writer.Write(1u);writer.Write(0u);writer.Write(3u);writer.Write(1u);foreach(double value in new double[]{0,0,0,1,0,0,0,1,0})writer.Write(value);writer.Write((ushort)0);writer.Write((ushort)1);writer.Write((ushort)2);writer.Write((ushort)1000);}
    if(Fault=="settings_after_export")Settings["solidShading"]=false;
   }
   public void ClearOwnSelection(){Clears++;if(Fault=="clear_throw")throw new IOException("Unknown own selection clear.");Selected.Clear();if(Fault=="clear_no_effect")Selected.Add(new Dictionary<string,object>{{"type","SOLID"},{"name","Synthetic_40"}});}
   public void Dispose(){}
  }
  internal static int Run() {
   Require(File.Exists(Path.Combine(Program.Root,".geometry-export-executor-fixture")),"Explicit isolated export executor marker required; no CAD.");var rows=new List<Dictionary<string,object>>();
   foreach(string fault in new[]{"control","mixed_targets","inactive_level","ambiguous_name","unsafe_name","wrong_mapping","unsupported_translator","invalid_tolerance","extra_settings","target_sha","busy_executor","claimed_context","select_throw","wrong_selection","late_document","retained_document","settings_after_select","selection_collision","export_throw","no_output","malformed_output","output_directory","settings_after_export","clear_throw","clear_no_effect","existing_export_fence"}) {
    var f=new OwnedOperationPlanTests.Fixture(true,true);f.Snapshot["levelsContainingEntities"]=new[]{new Dictionary<string,object>{{"number",0},{"name","Synthetic"},{"activeRaw",fault=="inactive_level"?0:1}}};var inventory=EntitySets.Inventory(f.Snapshot);if(fault=="ambiguous_name"){inventory[1]["type"]="SOLID";inventory[1]["name"]=inventory[0]["name"];}if(fault=="unsafe_name")inventory[0]["name"]="Cannot ' inject";
    var keys=fault=="mixed_targets"?new[]{new[]{40,5},new[]{21,8}}:new[]{new[]{40,5}};var parameters=OwnedGeometryExportTargetTests.Rebind(f,f.Snapshot,null,keys);string targetId=Guid.NewGuid().ToString("N");var prepared=OwnedGeometryExportTargets.Prepare(f.Root,targetId,parameters);Require(Equals(prepared["state"],"owned_geometry_export_target_prepared_files"),"Own export target setup failed: "+Program.Json.Serialize(prepared));
    var context=new Context(f){Fault=fault,TargetPath=OwnedGeometryExportTargets.TargetPath(f.Root,targetId)};var args=new Dictionary<string,object>{{"targetId",targetId},{"targetSha256",prepared["targetSha256"]}};
    if(fault=="unsupported_translator")context.Settings["translator"]="unqualified_external";if(fault=="invalid_tolerance")context.Settings["triangulationToleranceRaw"]=double.NaN;if(fault=="extra_settings")context.Settings["command"]="Never execute";if(fault=="target_sha")args["targetSha256"]=new string('f',64);
    var binding=Program.Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(Path.Combine(f.Root,"documentbindings",(string)parameters["bindingId"]+".json")));string exportFence=OwnedGeometryExportTargets.ExportFencePath(f.Root,(string)binding["copyId"]);if(fault=="existing_export_fence")File.WriteAllText(exportFence,"Prior unknown export.");
    var before=Hashes(f.Root);FileStream busy=null;if(fault=="busy_executor")busy=new FileStream(Path.Combine(f.Root,"operations","executor.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None);string id=Guid.NewGuid().ToString("N");Dictionary<string,object> result;try{result=OwnedGeometryExport.Execute(f.Root,id,args,context);}finally{if(busy!=null)busy.Dispose();}
    bool control=fault=="control"||fault=="mixed_targets";bool changed=context.Adds+context.Exports+context.Clears>0;Require(Equals(result["state"],control?"owned_geometry_export_executed_unverified":changed?"owned_geometry_export_outcome_unknown":"owned_geometry_export_rejected_before_change"),fault+": "+Program.Json.Serialize(result));Require(before.All(p=>Program.Hash(p.Key)==p.Value),"Original protected files changed.");Require(Equals(result["geometryVerified"],false)&&Equals(result["copyFenceReleased"],false)&&Equals(result["nativeProviderQualified"],false)&&Equals(result["geometryMutationAttempted"],false)&&Equals(result["cadSaveAttempted"],false),"Unsupported authority.");
    if(fault=="claimed_context")Require(Equals(result["recordedJournalState"],"rejected_before_change")&&!result.ContainsKey("journalError"),"Rejected claimed context missing independent source evidence.");
    if(control)Require(context.Adds==keys.Length&&context.Exports==1&&context.Clears==1&&context.Selected.Count==0&&Equals(result["meshParsed"],true),"Wrong known selection/export/restore sequence.");if(new[]{"select_throw","wrong_selection","late_document","settings_after_select","selection_collision"}.Contains(fault))Require(context.Exports==0&&context.Clears==0,"Unknown selection continued or cleaned up.");if(new[]{"export_throw","no_output","malformed_output","output_directory","settings_after_export"}.Contains(fault))Require(context.Exports==1&&context.Clears==0,"Unknown export retried/cleaned up.");
    if(File.Exists(exportFence)) {int calls=context.Adds+context.Exports+context.Clears;var replay=OwnedGeometryExport.Execute(f.Root,Guid.NewGuid().ToString("N"),args,context);Require(Equals(replay["state"],"owned_geometry_export_rejected_before_change")&&context.Adds+context.Exports+context.Clears==calls,fault+": claimed export replay performed callbacks.");}
    if(File.Exists(exportFence)) {var second=OwnedGeometryExportTargets.Prepare(f.Root,Guid.NewGuid().ToString("N"),parameters);Require(Equals(second["state"],"owned_geometry_export_target_rejected"),"Fenced copy allowed another export target.");bool refused=false;try{OwnedSaveTargets.NoFence(f.Root,(string)binding["copyId"]);}catch(InvalidDataException){refused=true;}Require(refused,"Fenced copy allowed SaveAs/mutation gate.");}
    rows.Add(new Dictionary<string,object>{{"fault",fault},{"root",f.Root},{"operationId",id},{"targetId",targetId},{"result",result},{"adds",context.Adds},{"exports",context.Exports},{"clears",context.Clears},{"protectedHashes",before},{"artifactHashes",Hashes(f.Root)},{"cadConnectionAttempted",false}});
   }
   Directory.CreateDirectory(Path.Combine(Program.Root,"reports"));NativeJournal.Freeze(Path.Combine(Program.Root,"reports","geometry-export-executor-tests.json"),new Dictionary<string,object>{{"state","passed"},{"rows",rows},{"cadConnectionAttempted",false}});Console.WriteLine("PASS: "+rows.Count+" guarded owned geometry export executor cases; fake contexts only.");return rows.Count;
  }
 }
}
